func TestShouldSkipDataConnectorReadyPoll(t *testing.T) {
	cases := map[string]struct {
		dataSource string
		syncMode   string
		want       bool
	}{
		"bigquery streaming": {
			dataSource: "bigquery",
			syncMode:   "STREAMING",
			want:       true,
		},
		"bigquery streaming case-insensitive": {
			dataSource: "BigQuery",
			syncMode:   "streaming",
			want:       true,
		},
		"bigquery periodic": {
			dataSource: "bigquery",
			syncMode:   "PERIODIC",
			want:       false,
		},
		"bigquery unset sync mode": {
			dataSource: "bigquery",
			syncMode:   "",
			want:       false,
		},
		"non-bigquery streaming": {
			dataSource: "gcs",
			syncMode:   "STREAMING",
			want:       false,
		},
		"third-party periodic": {
			dataSource: "jira",
			syncMode:   "PERIODIC",
			want:       false,
		},
	}

	for tn, tc := range cases {
		t.Run(tn, func(t *testing.T) {
			if got := shouldSkipDataConnectorReadyPoll(tc.dataSource, tc.syncMode); got != tc.want {
				t.Errorf("shouldSkipDataConnectorReadyPoll(%q, %q) = %v, want %v", tc.dataSource, tc.syncMode, got, tc.want)
			}
		})
	}
}

