func TestWaitForDataConnectorReady(t *testing.T) {
	const wantID = "projects/example-project/locations/global/collections/example-collection/dataConnector"

	initResourceData := func(t *testing.T) *schema.ResourceData {
		t.Helper()
		d := ResourceDiscoveryEngineDataConnector().TestResourceData()
		d.SetId(wantID)
		_ = d.Set("project", "example-project")
		_ = d.Set("location", "global")
		_ = d.Set("collection_id", "example-collection")
		return d
	}

	t.Run("polls until state leaves CREATING", func(t *testing.T) {
		var calls int32
		cfg := newDataConnectorTestConfig(t, func(w http.ResponseWriter, r *http.Request) {
			n := atomic.AddInt32(&calls, 1)
			state := "CREATING"
			if n >= 2 {
				state = "ACTIVE"
			}
			w.Header().Set("Content-Type", "application/json")
			_ = json.NewEncoder(w).Encode(map[string]interface{}{
				"name":       wantID,
				"dataSource": "onedrive_federated_search",
				"state":      state,
			})
		})

		d := initResourceData(t)
		if err := waitForDataConnectorReady(d, cfg, 10*time.Second); err != nil {
			t.Fatalf("unexpected error: %v", err)
		}
		if got := atomic.LoadInt32(&calls); got != 2 {
			t.Errorf("expected 2 GET calls, got %d", got)
		}
		if got := d.Get("state").(string); got != "ACTIVE" {
			t.Errorf("expected state ACTIVE, got %q", got)
		}
	})

	t.Run("polls until actionState leaves CREATING", func(t *testing.T) {
		var calls int32
		cfg := newDataConnectorTestConfig(t, func(w http.ResponseWriter, r *http.Request) {
			n := atomic.AddInt32(&calls, 1)
			actionState := "CREATING"
			if n >= 2 {
				actionState = "ACTIVE"
			}
			w.Header().Set("Content-Type", "application/json")
			_ = json.NewEncoder(w).Encode(map[string]interface{}{
				"name":        wantID,
				"dataSource":  "jira",
				"state":       "ACTIVE",
				"actionState": actionState,
			})
		})

		d := initResourceData(t)
		if err := waitForDataConnectorReady(d, cfg, 10*time.Second); err != nil {
			t.Fatalf("unexpected error: %v", err)
		}
		if got := atomic.LoadInt32(&calls); got != 2 {
			t.Errorf("expected 2 GET calls, got %d", got)
		}
		if got := d.Get("action_state").(string); got != "ACTIVE" {
			t.Errorf("expected action_state ACTIVE, got %q", got)
		}
	})

	for _, terminalState := range []string{"INITIALIZATION_FAILED", "FAILED"} {
		t.Run("does not error on terminal state "+terminalState, func(t *testing.T) {
			cfg := newDataConnectorTestConfig(t, func(w http.ResponseWriter, r *http.Request) {
				w.Header().Set("Content-Type", "application/json")
				_ = json.NewEncoder(w).Encode(map[string]interface{}{
					"name":              wantID,
					"dataSource":        "jira",
					"state":             terminalState,
					"actionState":       terminalState,
					"staticIpAddresses": []string{"203.0.113.10"},
				})
			})

			d := initResourceData(t)
			if err := waitForDataConnectorReady(d, cfg, 5*time.Second); err != nil {
				t.Fatalf("unexpected error for state %s: %v", terminalState, err)
			}
			if got := d.Get("state").(string); got != terminalState {
				t.Errorf("expected state %q, got %q", terminalState, got)
			}
		})
	}

	t.Run("errors if resource returns 404 during creation", func(t *testing.T) {
		cfg := newDataConnectorTestConfig(t, func(w http.ResponseWriter, r *http.Request) {
			http.Error(w, `{"error":{"code":404,"message":"not found"}}`, http.StatusNotFound)
		})

		d := initResourceData(t)
		if err := waitForDataConnectorReady(d, cfg, 5*time.Second); err == nil {
			t.Fatal("expected error on 404 during creation, got nil")
		}
	})
}

func TestResourceDiscoveryEngineDataConnectorCreate(t *testing.T) {
	const wantID = "projects/example-project/locations/global/collections/example-collection/dataConnector"
	const createPath = "/projects/example-project/locations/global:setUpDataConnectorV2"
	const getPath = "/" + wantID

	newCreateResourceData := func(t *testing.T, dataSource, syncMode string) *schema.ResourceData {
		t.Helper()
		d := ResourceDiscoveryEngineDataConnector().TestResourceData()
		for k, v := range map[string]interface{}{
			"project":                 "example-project",
			"location":                "global",
			"collection_id":           "example-collection",
			"collection_display_name": "Example Collection",
			"data_source":             dataSource,
			"sync_mode":               syncMode,
		} {
			if err := d.Set(k, v); err != nil {
				t.Fatalf("d.Set(%q): %v", k, err)
			}
		}
		return d
	}

	for _, terminalState := range []string{"ACTIVE", "FAILED", "INITIALIZATION_FAILED"} {
		t.Run("polls CREATING to terminal state "+terminalState, func(t *testing.T) {
			var postCalls, getCalls int32
			wantJSONActionParams := `{"auth_type":"OAUTH","pkce_support_enabled":true}`

			cfg := newDataConnectorTestConfig(t, func(w http.ResponseWriter, r *http.Request) {
				w.Header().Set("Content-Type", "application/json")
				switch {
				case r.Method == http.MethodPost && r.URL.Path == createPath:
					atomic.AddInt32(&postCalls, 1)
					body, err := io.ReadAll(r.Body)
					if err != nil {
						http.Error(w, err.Error(), http.StatusInternalServerError)
						return
					}
					var payload map[string]interface{}
					if err := json.Unmarshal(body, &payload); err != nil {
						http.Error(w, err.Error(), http.StatusBadRequest)
						return
					}
					ac, _ := payload["actionConfig"].(map[string]interface{})
					if got, _ := ac["jsonActionParams"].(string); got != wantJSONActionParams {
						http.Error(w, fmt.Sprintf("jsonActionParams = %q, want %q", got, wantJSONActionParams), http.StatusBadRequest)
						return
					}
					_ = json.NewEncoder(w).Encode(map[string]interface{}{
						"name": "projects/example-project/locations/global/operations/create-data-connector-op",
						"done": true,
					})
				case r.Method == http.MethodGet && r.URL.Path == getPath:
					n := atomic.AddInt32(&getCalls, 1)
					state := "CREATING"
					actionState := "CREATING"
					if n >= 2 {
						state = terminalState
						actionState = terminalState
					}
					_ = json.NewEncoder(w).Encode(map[string]interface{}{
						"name":                         wantID,
						"dataSource":                   "jira",
						"syncMode":                     "PERIODIC",
						"state":                        state,
						"actionState":                  actionState,
						"staticIpAddresses":            []string{"203.0.113.10"},
						"privateConnectivityProjectId": "example-tenant-project",
					})
				default:
					http.Error(w, fmt.Sprintf("unexpected request: %s %s", r.Method, r.URL.Path), http.StatusNotFound)
				}
			})

			d := newCreateResourceData(t, "jira", "PERIODIC")
			if err := d.Set("action_config", []interface{}{
				map[string]interface{}{
					"json_action_params":    wantJSONActionParams,
					"create_bap_connection": true,
				},
			}); err != nil {
				t.Fatalf("d.Set(action_config): %v", err)
			}

			if err := ResourceDiscoveryEngineDataConnector().Create(d, cfg); err != nil {
				t.Fatalf("Create failed for terminal state %s: %v", terminalState, err)
			}
			if got := atomic.LoadInt32(&postCalls); got != 1 {
				t.Errorf("expected 1 POST call, got %d", got)
			}
			if got := atomic.LoadInt32(&getCalls); got != 3 {
				t.Errorf("expected 3 GET calls (2 readiness polls + 1 final Read), got %d", got)
			}
			if got := d.Id(); got != wantID {
				t.Errorf("d.Id() = %q, want %q", got, wantID)
			}
			if got := d.Get("state").(string); got != terminalState {
				t.Errorf("state = %q, want %q", got, terminalState)
			}
			if got := d.Get("action_state").(string); got != terminalState {
				t.Errorf("action_state = %q, want %q", got, terminalState)
			}
			if got := d.Get("private_connectivity_project_id").(string); got != "example-tenant-project" {
				t.Errorf("private_connectivity_project_id = %q, want %q", got, "example-tenant-project")
			}
		})
	}

	t.Run("skips post_create readiness poll for bigquery STREAMING", func(t *testing.T) {
		var postCalls, getCalls int32
		cfg := newDataConnectorTestConfig(t, func(w http.ResponseWriter, r *http.Request) {
			w.Header().Set("Content-Type", "application/json")
			switch {
			case r.Method == http.MethodPost && r.URL.Path == createPath:
				atomic.AddInt32(&postCalls, 1)
				_ = json.NewEncoder(w).Encode(map[string]interface{}{
					"name": "projects/example-project/locations/global/operations/create-bq-streaming-op",
					"done": true,
				})
			case r.Method == http.MethodGet && r.URL.Path == getPath:
				n := atomic.AddInt32(&getCalls, 1)
				if n > 1 {
					http.Error(w, "unexpected readiness poll GET for bigquery STREAMING", http.StatusInternalServerError)
					return
				}
				_ = json.NewEncoder(w).Encode(map[string]interface{}{
					"name":       wantID,
					"dataSource": "bigquery",
					"syncMode":   "STREAMING",
					"state":      "CREATING",
				})
			default:
				http.Error(w, fmt.Sprintf("unexpected request: %s %s", r.Method, r.URL.Path), http.StatusNotFound)
			}
		})

		d := newCreateResourceData(t, "bigquery", "STREAMING")
		if err := ResourceDiscoveryEngineDataConnector().Create(d, cfg); err != nil {
			t.Fatalf("Create failed for bigquery STREAMING: %v", err)
		}
		if got := atomic.LoadInt32(&postCalls); got != 1 {
			t.Errorf("expected 1 POST call, got %d", got)
		}
		if got := atomic.LoadInt32(&getCalls); got != 1 {
			t.Errorf("expected 1 GET call (final Read only, skipping post_create poll), got %d", got)
		}
		if got := d.Id(); got != wantID {
			t.Errorf("d.Id() = %q, want %q", got, wantID)
		}
		if got := d.Get("state").(string); got != "CREATING" {
			t.Errorf("state = %q, want CREATING", got)
		}
	})

	t.Run("preserves full resource ID in error on HTTP 404 during post_create polling", func(t *testing.T) {
		var postCalls, getCalls int32
		cfg := newDataConnectorTestConfig(t, func(w http.ResponseWriter, r *http.Request) {
			w.Header().Set("Content-Type", "application/json")
			switch {
			case r.Method == http.MethodPost && r.URL.Path == createPath:
				atomic.AddInt32(&postCalls, 1)
				_ = json.NewEncoder(w).Encode(map[string]interface{}{
					"name": "projects/example-project/locations/global/operations/create-404-op",
					"done": true,
				})
			case r.Method == http.MethodGet && r.URL.Path == getPath:
				atomic.AddInt32(&getCalls, 1)
				http.Error(w, `{"error":{"code":404,"message":"not found"}}`, http.StatusNotFound)
			default:
				http.Error(w, fmt.Sprintf("unexpected request: %s %s", r.Method, r.URL.Path), http.StatusNotFound)
			}
		})

		d := newCreateResourceData(t, "jira", "PERIODIC")
		err := ResourceDiscoveryEngineDataConnector().Create(d, cfg)
		if err == nil {
			t.Fatal("expected error on HTTP 404 during post_create polling, got nil")
		}
		if strings.Contains(err.Error(), `DataConnector ""`) {
			t.Errorf("error formatted empty DataConnector ID after HandleNotFoundError cleared d.Id(): %v", err)
		}
		wantPrefix := fmt.Sprintf("Error waiting for DataConnector %q to finish initializing during creation:", wantID)
		if !strings.Contains(err.Error(), wantPrefix) {
			t.Errorf("error %q does not contain expected prefix %q", err.Error(), wantPrefix)
		}
		if got := d.Id(); got != "" {
			t.Errorf("expected HandleNotFoundError to clear d.Id(), got %q", got)
		}
	})
}
